// Binary search over a sorted range table.
static bool InRanges(const Range* table, std::size_t n, char32_t cp) noexcept {
    std::size_t lo = 0, hi = n;
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (cp < table[mid].Lo)
            hi = mid;
        else if (cp > table[mid].Hi)
            lo = mid + 1;
        else
            return true;
    }
    return false;
}

int Wcwidth(char32_t cp) noexcept {
    // C0 controls and DEL.
    if (cp < 0x20 || cp == 0x7F) return -1;
    // C1 controls (8-bit; in UTF-8 terminals these are continuation bytes
    // and should not appear here, but be defensive).
    if (cp >= 0x80 && cp < 0xA0) return -1;
    // Zero-width (combining marks, default-ignorable, etc.).
    if (InRanges(kZeroWidth, sizeof(kZeroWidth) / sizeof(*kZeroWidth), cp))
        return 0;
    // Wide / Fullwidth.
    if (InRanges(kWide, sizeof(kWide) / sizeof(*kWide), cp)) return 2;
    return 1;
}

